<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $query=function_exists('nvconsult_v2_get_latest_articles')?nvconsult_v2_get_latest_articles(3):new WP_Query(array('post_type'=>'nvconsult_article','post_status'=>'publish','posts_per_page'=>3)); ?>
<section class="section"><div class="section-inner"><?php nvconsultv2_render_section_heading( 'knowledge-centre', __( 'Knowledge Centre', 'nvconsult-theme-v2' ), __( 'Fresh advice, destination guides, and application insights.', 'nvconsult-theme-v2' ) ); ?><div class="articles-grid"><?php if($query->have_posts()): while($query->have_posts()): $query->the_post(); $terms=get_the_terms(get_the_ID(),'nvconsult_article_category'); ?><article class="article-card"><div class="article-card__image"><?php if(has_post_thumbnail()): the_post_thumbnail('large'); endif; ?></div><div class="article-card__content"><?php if(!empty($terms)&&!is_wp_error($terms)): ?><span class="category-badge"><?php echo esc_html( $terms[0]->name ); ?></span><?php endif; ?><h3><?php the_title(); ?></h3><p class="article-card__meta"><?php echo esc_html( get_the_date() ); ?></p><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 18 ) ); ?></p><a class="btn-outline" href="<?php the_permalink(); ?>"><?php esc_html_e( 'Read More →', 'nvconsult-theme-v2' ); ?></a></div></article><?php endwhile; wp_reset_postdata(); else: for($i=0;$i<3;$i++): ?><article class="article-card"><div class="article-card__content"><span class="category-badge"><?php esc_html_e( 'Guide', 'nvconsult-theme-v2' ); ?></span><h3><?php esc_html_e( 'Add articles to populate the knowledge centre', 'nvconsult-theme-v2' ); ?></h3><p><?php esc_html_e( 'Create article entries in wp-admin → Articles.', 'nvconsult-theme-v2' ); ?></p></div></article><?php endfor; endif; ?></div><p style="margin-top:24px;"><a class="btn-primary" href="<?php echo esc_url( get_post_type_archive_link( 'nvconsult_article' ) ); ?>"><?php esc_html_e( 'View All Articles →', 'nvconsult-theme-v2' ); ?></a></p></div></section>
